function agents(){view.innerHTML=head('AGENT CONTROL ROOM','Agents werken binnen <em>vaste grenzen.</em>','Zie acties, tools, budgetten en approvals. Geen verborgen redeneringen.')+`<div class="page-grid">${data.agents.map(x=>`<article class="item-card"><div class="item-top"><span class="agent-status ${x.status}">${x.status}</span>${badge(x.version)}</div><h3>${x.name}</h3><p>${x.task}</p><span class="mini">Tools: ${x.tools.join(', ')} · budget ${x.budget}</span><div class="actions">${x.status==='stopped'?badge('Menselijke heractivatie vereist','orange'):button(x.status==='paused'?'Hervatten':'Pauzeren','agent',x.id)+button('Kill switch','agent-kill',x.id,'danger')}</div></article>`).join('')}</div>`}
function managedAgents(){const brand=agentRegistryData?.brand||osData?.brand;if(!agentRegistryData){view.innerHTML=head('AGENT CONTROL ROOM',`${escapeText(brand?.name||activeCompany.name)} agents <em>veilig geblokkeerd.</em>`,'De duurzame agentregistry kon niet veilig worden geladen. Demo-agents worden nooit als live waarheid gebruikt.',badge('Fail-closed','orange'));return}const agents=agentRegistryData.agents||[],summary=agentRegistryData.summary||{};view.innerHTML=head('AGENT CONTROL ROOM',`${escapeText(brand.name)} agents <em>zonder schijncontrole.</em>`,'Alleen duurzaam geregistreerde identiteit, versie, grenzen en waarnemingen. Bediening en externe writes blijven uit.',badge('Supabase-registry','green'))+`<section class="grid metrics hud-metrics"><article class="metric"><span class="metric-label">Geregistreerd</span><strong>${summary.registeredAgents||0}</strong><small>duurzame agentrecords</small></article><article class="metric"><span class="metric-label">Waargenomen</span><strong>${summary.observedAgents||0}</strong><small>met actuele runtime-evidence</small></article><article class="metric"><span class="metric-label">Agentbediening</span><strong>UIT</strong><small>geen generieke acties</small></article><article class="metric"><span class="metric-label">Externe writes</span><strong>UIT</strong><small>databasecontract</small></article></section><section class="os-section"><div class="os-section-head"><div><span class="metric-label">DURABLE AGENT REGISTRY</span><h2>Bestuurbare feiten per agent</h2></div>${badge(`${agents.length} zichtbaar`,agents.length?'green':'orange')}</div>${agents.length?`<div class="page-grid">${agents.map(agent=>`<article class="item-card"><div class="item-top">${badge(escapeText(agent.lifecycleStatus),agent.lifecycleStatus==='registered'?'green':'orange')}${badge(escapeText(agent.runtimeStatus),agent.runtimeStatus==='running'?'green':'')}</div><h3>${escapeText(agent.name)}</h3><p>${escapeText(agent.purpose)}</p><span class="mini">Versie ${escapeText(agent.version)} · risicoplafond ${escapeText(agent.riskCeiling)} · bron ${escapeText(agent.sourceQuality)}</span><span class="mini">Tools: ${(agent.tools||[]).map(escapeText).join(', ')||'geen'} · budget ${agent.budgetLimitMinor===null?'niet toegewezen':formatMoney(agent.budgetLimitMinor)}</span><div class="actions">${badge('Bediening geblokkeerd','orange')}</div></article>`).join('')}</div>`:'<div class="honest-empty">De duurzame registry is actief, maar bevat nog geen agentrecords voor deze operating brand. Daardoor worden geen namen, activiteit, budgetten of bedieningsknoppen verzonnen.</div>'}</section>`}
function accessManagement(){if(!accessData){view.innerHTML=head('TOEGANG & ROLLEN','Organisatietoegang is <em>niet beschikbaar.</em>','Het server-side toegangscontract kon niet veilig worden geladen.',badge('Fail-closed','orange'));return}const members=accessData.members||[],requests=accessData.requests||[],canManage=accessData.viewer?.canManageAccess===true;view.innerHTML=head('TOEGANG & ROLLEN',`${escapeText(accessData.organization.legalName)} <em>veilig beheren.</em>`,'Eén login per persoon, minimale rechten per organisatie of operating brand en altijd een menselijke approval vóór activatie.',badge(`${members.length} actief profiel${members.length===1?'':'en'}`,'green'))+`<section class="grid metrics hud-metrics"><article class="metric"><span class="metric-label">Profielen</span><strong>${members.length}</strong><small>met organisatiescope</small></article><article class="metric"><span class="metric-label">Approval vereist</span><strong>${accessData.counts?.approvalRequired||0}</strong><small>R2-toegangsverzoeken</small></article><article class="metric"><span class="metric-label">Providerinvites</span><strong>UIT</strong><small>geen e-mail verzonden</small></article><article class="metric"><span class="metric-label">Externe writes</span><strong>UIT</strong><small>databaseconstraint</small></article></section><section class="os-section"><div class="os-section-head"><div><span class="metric-label">IAM ROSTER</span><h2>Wie heeft welke scope?</h2></div>${badge(accessData.externalWrites?'Writes actief':'Writes uit',accessData.externalWrites?'orange':'green')}</div><div class="page-grid">${members.map(member=>`<article class="item-card"><div class="item-top">${badge(member.status,member.status==='active'?'green':'orange')}${badge(member.mfaRequired?'MFA verplicht':'MFA niet verplicht',member.mfaRequired?'green':'orange')}</div><h3>${escapeText(member.displayName)}</h3><p>${escapeText(member.email)}</p>${member.memberships.map(membership=>`<div class="micro-row"><span>${membership.scope==='legal_entity'?'ORG':'BR'}</span><strong>${escapeText(membership.role)}</strong>&nbsp;· ${escapeText(membership.brand?.name||accessData.organization.tradingName||accessData.organization.legalName)} · ${escapeText(membership.status)}</div>`).join('')}</article>`).join('')}</div></section><section class="os-section"><div class="os-section-head"><div><span class="metric-label">PENDING ACCESS</span><h2>Gestagede verzoeken</h2></div>${badge(`${requests.length} totaal`,requests.length?'orange':'green')}</div>${requests.length?requests.map(request=>`<article class="exception-row"><span>R2</span><div><h3>${escapeText(request.displayName)} · ${escapeText(request.requestedRole)}</h3><p>${escapeText(request.email)} · ${request.scope==='legal_entity'?'hele organisatie':escapeText(request.brand?.name||'operating brand')}</p><small>Context V${request.contextVersion} · ${new Date(request.requestedAt).toLocaleString('nl-NL')} · invite ${request.providerInviteSent?'verzonden':'niet verzonden'}</small></div>${badge(request.status,request.status==='approved'?'green':'orange')}</article>`).join(''):'<div class="honest-empty">Geen toegangsverzoeken. Er is niets naar een provider verstuurd.</div>'}</section>${canManage?`<section class="os-section"><div class="os-section-head"><div><span class="metric-label">R2 ACCESS REQUEST</span><h2>Toegang veilig voorbereiden</h2></div>${badge('Alleen staging','orange')}</div><p class="section-note">Dit maakt een pending approval, audit event en kosteloze usage-regel. Het maakt geen account of membership aan en verstuurt geen uitnodiging.</p><form id="accessRequestForm" class="page-grid"><article class="item-card"><div class="field"><label for="accessName">Naam</label><input id="accessName" name="displayName" required minlength="2" maxlength="120" autocomplete="name" placeholder="Naam van teamlid"></div><div class="field"><label for="accessEmail">E-mailadres</label><input id="accessEmail" name="email" required type="email" maxlength="254" autocomplete="email" placeholder="naam@bedrijf.nl"></div></article><article class="item-card"><div class="field"><label for="accessRole">Rol</label><select id="accessRole" name="role" required><option value="viewer">Viewer</option><option value="operator">Operator</option><option value="finance">Finance</option><option value="auditor">Auditor</option><option value="admin">Admin</option></select></div><div class="field"><label for="accessBrand">Scope</label><select id="accessBrand" name="brandSlug"><option value="">Hele organisatie</option>${viewer.companies.map(company=>`<option value="${escapeText(company.id)}">${escapeText(company.name)}</option>`).join('')}</select></div><button class="button" type="submit">Maak pending approval</button></article></form></section>`:''}`}
function onboardingPanel(){if(!onboardingData)return'';const steps=onboardingData.steps||[],requests=onboardingData.connectorRequests||[],completed=steps.filter(step=>step.status==='completed').length,problems=steps.filter(step=>['blocked','validation_required'].includes(step.status)).length,live=liveHealthData,canManage=onboardingData.viewer?.canManageConnectors===true;return`<section class="os-section"><div class="os-section-head"><div><span class="metric-label">SOFTWARE LAUNCH CONTROL</span><h2>${escapeText(onboardingData.brand.name)} koppelen in zes beheerste stappen</h2></div><div class="actions">${badge(`${completed}/${steps.length} voltooid`,completed===steps.length?'green':'orange')}${button('Sla actuele controle op','monitor-brand',onboardingData.brand.slug)}</div></div>${live?`<article class="exception-row"><span>${live.status==='healthy'?'OK':'P2'}</span><div><h3>Live read-only probe · ${escapeText(live.status)}</h3><p>${live.errorCode?`Actuele foutcode: ${escapeText(live.errorCode)}`:'Health en basisafhankelijkheden antwoorden zoals verwacht.'}</p><small>${new Date(live.observedAt).toLocaleString('nl-NL')} · ${escapeText(live.sourceQuality)}</small></div>${badge(live.externalWrites?'Writes actief':'Writes uit',live.externalWrites?'orange':'green')}</article>`:''}<p class="section-note">Eén centrale login; iedere provider start read-only. Alleen een expliciete klik legt auditbewijs vast. OAuth en R3-acties blijven menselijk geblokkeerd. ${problems} stap${problems===1?'':'pen'} vraagt aandacht.</p><div class="page-grid">${steps.map(step=>{const request=requests.find(item=>item.stepKey===step.key&&['approval_required','approved'].includes(item.status)),stageable=canManage&&step.authorizationRequired&&step.connector&&!['completed','skipped'].includes(step.status)&&!request;return`<article class="item-card"><div class="item-top"><span class="metric-label">STAP ${String(step.position).padStart(2,'0')}</span>${badge(step.status,step.status==='completed'?'green':['blocked','validation_required'].includes(step.status)?'orange':'')}</div><h3>${escapeText(step.title)}</h3><p>${escapeText(step.instructions)}</p>${step.connector?`<span class="mini">Connector: ${escapeText(step.connector.name)} · ${escapeText(step.connector.authorizationType)}</span>`:''}${step.errorCode?`<div class="micro-row"><span>!</span><strong>${escapeText(step.errorCode)}</strong></div>`:''}${request?`<div class="micro-row"><span>${escapeText(request.riskClass)}</span><strong>Intern verzoek: ${escapeText(request.status)}</strong></div><span class="mini">Providerautorisatie niet gestart · geen account of credentials gekoppeld</span>${canManage&&request.status==='approval_required'?`<div class="actions"><button class="button secondary" type="button" data-action="connector-decision" data-id="${escapeText(request.id)}" data-decision="approved">Intern goedkeuren</button><button class="button danger" type="button" data-action="connector-decision" data-id="${escapeText(request.id)}" data-decision="rejected">Afwijzen</button></div>`:''}`:''}${stageable?`<div class="actions"><button class="button secondary" type="button" data-action="connector-stage" data-id="${escapeText(step.key)}">Alleen intern voorbereiden</button></div><span class="mini">OAuth, discovery, credentials en externe writes blijven geblokkeerd</span>`:''}</article>`}).join('')}</div>${(onboardingData.connections||[]).map(connection=>connection.latestHealth?`<article class="exception-row"><span>${escapeText(connection.latestHealth.severity)}</span><div><h3>${escapeText(connection.connectorKey)} · ${escapeText(connection.latestHealth.status)}</h3><p>${escapeText(connection.latestHealth.summary)}</p><small>Foutcode: ${escapeText(connection.latestHealth.errorCode||'geen')}</small></div>${badge(connection.status,connection.status==='connected'?'green':'orange')}</article>`:'').join('')}</section>`}
function renderAccessDecisionControls(){if(path!=='/control-center/access'||accessData?.viewer?.canManageAccess!==true)return;const requestRows=[...view.querySelectorAll('.exception-row')];(accessData.requests||[]).forEach((request,index)=>{const row=requestRows[index];if(!row||request.status!=='approval_required')return;const details=row.querySelector('small');if(details)details.textContent+=` · membership niet toegepast`;const actions=document.createElement('div');actions.className='actions';[['approved','Goedkeuren','secondary'],['rejected','Afwijzen','danger']].forEach(([decision,label,kind])=>{const control=document.createElement('button');control.type='button';control.className=`button ${kind}`;control.dataset.action='access-decision';control.dataset.id=request.id;control.dataset.decision=decision;control.textContent=label;actions.append(control)});row.append(actions)})}
async function managedPost(endpoint,body,idempotencyKey){const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':idempotencyKey},body:JSON.stringify(body)});const result=await response.json();if(response.status===401){location.replace('/login');throw new Error('Sessie verlopen')}if(!response.ok)throw new Error(result.error||'De beheeractie kon niet veilig worden verwerkt.');return result}
async function refreshAccessRoster(){const response=await fetch('/api/v1/access/roster');if(response.status===401){location.replace('/login');throw new Error('Sessie verlopen')}if(!response.ok)throw new Error('Toegangsbeheer kon niet worden ververst');accessData=await response.json();render();renderAccessDecisionControls()}
async function refreshOnboarding(){const response=await fetch(`/api/v1/onboarding/brands/${encodeURIComponent(activeCompany.id)}`);if(response.status===401){location.replace('/login');throw new Error('Sessie verlopen')}if(!response.ok)throw new Error('Onboarding kon niet worden ververst');onboardingData=await response.json();render();renderManagedPanels()}
async function refreshBrandLaunches(){const response=await fetch('/api/v1/brand-launch/requests');if(response.status===401){location.replace('/login');throw new Error('Sessie verlopen')}if(!response.ok)throw new Error('Nieuwe softwareverzoeken konden niet worden ververst');brandLaunchData=await response.json();render();renderManagedPanels()}
async function refreshIncidents(){const portfolioView=path==='/control-center/portfolio',endpoint=portfolioView?'/api/v1/incidents':`/api/v1/incidents/brands/${encodeURIComponent(activeCompany.id)}`,response=await fetch(endpoint);if(!response.ok)throw new Error('Incidentstatus kon niet worden ververst');incidentsData=await response.json();render();renderManagedPanels()}
async function recordMonitoring(companyIds,target){target.disabled=true;const rootKey=`probe_${crypto.randomUUID()}`;try{const results=await Promise.all(companyIds.map(slug=>managedPost(`/api/v1/monitoring/probe/brands/${encodeURIComponent(slug)}`,{},`${rootKey}_${slug}`)));if(companyIds.length===1){liveHealthData=results[0].health;incidentsData=results[0].incidents;render();renderManagedPanels()}else await refreshIncidents();toast(`${companyIds.length} controle${companyIds.length===1?'':'s'} vastgelegd met auditbewijs.`)}finally{target.disabled=false}}
async function acknowledgeManagedIncident(incident,target){if(!confirm(`${incident.brand.name}: bevestigen dat incident ${incident.code} is gezien?`))return;target.disabled=true;try{await managedPost(`/api/v1/incidents/${encodeURIComponent(incident.id)}/acknowledge`,{contextVersion:incident.contextVersion},`ack_${crypto.randomUUID()}`);await refreshIncidents();toast('Incident bevestigd en als governed R1-commando gelogd.')}finally{target.disabled=false}}
function renderManagedPanels(){if(!internal)return;if(path==='/control-center/portfolio'){if(brandLaunchData)view.insertAdjacentHTML('beforeend',brandLaunchPanel());return}const implementationView=path.startsWith('/control-center/implementaties/');if(onboardingData&&(path==='/control-center'||implementationView))view.insertAdjacentHTML('beforeend',onboardingPanel());if(incidentsData&&(path==='/control-center'||implementationView||path==='/control-center/agents'))view.insertAdjacentHTML('beforeend',persistedIncidentPanel())}
async function command(action,payload={}){if(data.controlPlaneMode==='managed'){toast('Deze demoactie is niet actief in het managed control plane. Gebruik de specifieke duurzame beheeractie.',true);return false}const response=await fetch(`/api/v1/demo/command?${companyApiQuery}`,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({action,payload})});const result=await response.json();if(response.status===401){location.replace('/login');return false}if(!response.ok){toast(result.error||'Actie kon niet worden verwerkt.',true);return false}const refreshed=await fetch(`/api/v1/demo?${companyApiQuery}`);if(refreshed.status===401){location.replace('/login');return false}data=await refreshed.json();toast('Actie veilig verwerkt en gelogd.');render();return true}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action="access-decision"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();const request=accessData?.requests?.find(item=>item.id===target.dataset.id),decision=target.dataset.decision;if(!request||!['approved','rejected'].includes(decision)){toast('De verzoekcontext is gewijzigd; laad de pagina opnieuw.',true);return}const label=decision==='approved'?'goedkeuren':'afwijzen';if(!confirm(`${request.displayName} als ${request.requestedRole} ${label}? Dit registreert alleen het besluit. Er wordt geen account, membership of provideruitnodiging aangemaakt.`))return;target.disabled=true;try{await managedPost(`/api/v1/access/requests/${encodeURIComponent(request.id)}/decision`,{decision,contextVersion:request.contextVersion},`access_decision_${crypto.randomUUID()}`);await refreshAccessRoster();toast(`Toegangsverzoek ${decision==='approved'?'goedgekeurd':'afgewezen'}; activatie blijft geblokkeerd.`)}catch(error){toast(error.message,true)}finally{target.disabled=false}},true);
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action="connector-stage"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();const step=onboardingData?.steps?.find(item=>item.key===target.dataset.id);if(!step?.connector){toast('Connectorcontext is ververst; laad de pagina opnieuw.',true);return}if(!confirm(`${step.connector.name} alleen intern voorbereiden? Dit start geen OAuth, koppelt geen provideraccount, leest geen providerdata uit, bewaart geen credentials en voert geen externe writes uit.`))return;target.disabled=true;try{await managedPost(`/api/v1/onboarding/brands/${encodeURIComponent(activeCompany.id)}/connector-requests`,{stepKey:step.key,displayLabel:`${onboardingData.brand.name} ${step.connector.name}`},`connector_${crypto.randomUUID()}`);await refreshOnboarding();toast('Connectorverzoek intern gestaged; providerautorisatie blijft geblokkeerd.')}catch(error){toast(error.message,true)}finally{target.disabled=false}},true);
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action="connector-decision"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();const request=onboardingData?.connectorRequests?.find(item=>item.id===target.dataset.id),decision=target.dataset.decision;if(!request||!['approved','rejected'].includes(decision)){toast('De connectorcontext is gewijzigd; laad de pagina opnieuw.',true);return}const label=decision==='approved'?'intern goedkeuren':'afwijzen';if(!confirm(`${request.displayLabel} ${label}? Dit registreert alleen het interne besluit. OAuth, provideraccount, discovery, credentials en externe writes blijven geblokkeerd.`))return;target.disabled=true;try{await managedPost(`/api/v1/onboarding/brands/${encodeURIComponent(activeCompany.id)}/connector-requests/${encodeURIComponent(request.id)}/decision`,{decision,contextVersion:request.contextVersion},`connector_decision_${crypto.randomUUID()}`);await refreshOnboarding();toast(`Connectorverzoek ${decision==='approved'?'intern goedgekeurd':'afgewezen'}; providerautorisatie blijft geblokkeerd.`)}catch(error){toast(error.message,true)}finally{target.disabled=false}},true);
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action="brand-launch-decision"]');if(!target)return;event.preventDefault();event.stopImmediatePropagation();const request=brandLaunchData?.requests?.find(item=>item.id===target.dataset.id),decision=target.dataset.decision;if(!request||!['approved','rejected'].includes(decision)){toast('De softwarelaunchcontext is gewijzigd; laad de pagina opnieuw.',true);return}const label=decision==='approved'?'intern goedkeuren':'afwijzen';if(!confirm(`${request.name} ${label}? Dit registreert alleen het interne besluit. Er wordt geen brand, sandbox, onboardingrun, provideraccount of credential aangemaakt.`))return;target.disabled=true;try{await managedPost(`/api/v1/brand-launch/requests/${encodeURIComponent(request.id)}/decision`,{decision,contextVersion:request.contextVersion},`brand_launch_decision_${crypto.randomUUID()}`);await refreshBrandLaunches();toast(`Softwarelaunch ${decision==='approved'?'intern goedgekeurd':'afgewezen'}; er is nog niets aangemaakt of gekoppeld.`)}catch(error){toast(error.message,true)}finally{target.disabled=false}},true);
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;try{if(action==='company-toggle'){const menu=document.querySelector('.company-menu'),expanded=target.getAttribute('aria-expanded')==='true';target.setAttribute('aria-expanded',String(!expanded));menu.hidden=expanded;return}if(action==='company-select')return location.href=`/control-center?company=${encodeURIComponent(id)}`;if(action==='logout'){await fetch('/api/v1/session/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});return location.replace('/login')}if(action==='monitor-portfolio')return recordMonitoring(viewer.companies.map(company=>company.id),target);if(action==='monitor-brand')return recordMonitoring([id],target);if(action==='incident-ack'){const incident=incidentsData?.incidents?.find(item=>item.id===id);if(!incident)throw new Error('Incidentcontext is ververst; laad de pagina opnieuw.');return acknowledgeManagedIncident(incident,target)}if(action==='reset')return command('demo.reset');if(action==='login-role'){loginRole=id;document.querySelectorAll('[data-action="login-role"]').forEach(x=>x.classList.toggle('active',x===target));const internalRole=id==='internal';document.querySelector('#demoEmail').value=internalRole?'operator@autopilots.example':'demo@curacao-auto.example';const code=document.querySelector('#demoCode');if(code)code.value=internalRole?'autopilots-internal':'autopilots-demo';return}if(action==='requirement')return command('requirement.confirm',{id});if(action==='onboarding')return command('onboarding.toggle',{id});if(action==='integration-connect')return command('integration.connect',{id});if(action==='integration-test')return command('integration.test',{id});if(action==='task')return command('task.resolve',{id,decision:'approved'});if(action==='task-reject')return command('task.resolve',{id,decision:'rejected'});if(action==='task-escalate')return command('task.resolve',{id,decision:'escalated'});if(action==='approval-approve'||action==='approval-reject'){const item=data.approvals.find(approval=>approval.id===id);return command('approval.decide',{id,decision:action==='approval-approve'?'approved':'rejected',contextVersion:item.contextVersion})}if(action==='agent')return command('agent.toggle',{id});if(action==='agent-kill'){if(confirm('Demo-agent stoppen? Deze actie wordt in het audit trail gezet.'))return command('agent.kill',{id,reason:'Kill switch'})}if(action==='select-product')return command('product.select',{id});if(action==='payment'){const paid=await command('payment.complete',{reference:'demo_checkout_verified'});if(paid)return location.href='/betaling-geslaagd';return}if(action==='save-field'){const input=document.querySelector(`[data-room-field="${id}"]`);return command('dataroom.field',{id,value:input?.value||''})}if(action==='upload-document'){const file=document.querySelector('#demoFile')?.files?.[0];if(!file)throw new Error('Kies eerst een demobestand');return command('dataroom.document',{name:file.name})}if(action==='store-secret'){const label=document.querySelector('#secretLabel')?.value;const secret=document.querySelector('#secretValue')?.value;if(!label||!secret)throw new Error('Vul naam en secret in');document.querySelector('#secretValue').value='';return command('dataroom.secret',{label,value:secret})}if(action==='proposal')return location.href='/documenten';if(action==='play-scenario')return playScenario();if(action==='scenario'){document.querySelector('#scenarioTitle').textContent=scenariosFor(selectedProduct().id)[Number(id)];toast('Scenario geselecteerd.')}if(action==='test-filter')toast(`Filter actief: ${id}.`);if(action==='lifecycle')return command('lifecycle.advance')}catch(error){toast(error.message,true)}});
document.addEventListener('change',async event=>{const input=event.target.closest('[data-action="legal"]');if(!input)return;try{await command('legal.accept',{type:input.dataset.id,accepted:input.checked})}catch(error){toast(error.message,true)}});
document.addEventListener('submit',async event=>{if(event.target.id!=='brandLaunchForm')return;event.preventDefault();event.stopImmediatePropagation();const submit=event.target.querySelector('[type="submit"]'),form=new FormData(event.target),name=String(form.get('name')||''),slug=String(form.get('slug')||''),code=String(form.get('code')||''),riskProfile=String(form.get('riskProfile')||'standard');if(!confirm(`${name} alleen intern voorbereiden? Dit maakt geen brand, sandbox, onboardingrun, provideraccount, credentials of externe writes aan.`))return;submit.disabled=true;try{await managedPost('/api/v1/brand-launch/requests',{name,slug,code,riskProfile},`brand_launch_${crypto.randomUUID()}`);await refreshBrandLaunches();toast('Nieuw softwareverzoek intern gestaged; er is nog niets aangemaakt of gekoppeld.')}catch(error){toast(error.message,true)}finally{submit.disabled=false}},true);
document.addEventListener('submit',async event=>{if(event.target.id==='accessRequestForm'){event.preventDefault();const submit=event.target.querySelector('[type="submit"]'),form=new FormData(event.target);submit.disabled=true;try{await managedPost('/api/v1/access/requests',{displayName:String(form.get('displayName')||''),email:String(form.get('email')||''),role:String(form.get('role')||''),brandSlug:String(form.get('brandSlug')||'')},`access_${crypto.randomUUID()}`);await refreshAccessRoster();toast('Toegangsverzoek is alleen intern gestaged en wacht op menselijke approval.')}finally{submit.disabled=false}return}if(event.target.id==='mfaForm'){event.preventDefault();const error=document.querySelector('#mfaError'),submit=event.target.querySelector('[type="submit"]'),code=document.querySelector('#mfaCode')?.value.trim();error.hidden=true;submit.disabled=true;try{if(!pendingMfa)throw new Error('De tijdelijke inlogsessie is verlopen.');const response=await fetch('/api/v1/session/mfa/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...pendingMfa,code})});const result=await response.json();if(!response.ok)throw new Error(result.error||'De authenticatorcode kon niet worden bevestigd.');pendingMfa=null;return location.replace('/control-center/portfolio')}catch(mfaError){error.textContent=mfaError.message;error.hidden=false;submit.disabled=false}return}if(event.target.id!=='loginForm')return;event.preventDefault();const email=document.querySelector('#demoEmail')?.value.trim(),code=document.querySelector('#demoCode')?.value,error=document.querySelector('#loginError'),submit=event.target.querySelector('[type="submit"]'),managed=authCapabilities.provider==='supabase';error.hidden=true;submit.disabled=true;try{const response=await fetch('/api/v1/session/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(managed?{email}:{email,code,role:loginRole})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Inloggen is niet gelukt');if(managed){event.target.innerHTML=`<div class="eyebrow">INLOGLINK VERSTUURD</div><h3>Controleer je e-mail</h3><p>${escapeText(result.message)}</p><span class="mini">De link is eenmalig en brengt je terug naar deze beveiligde omgeving.</span>`;return}location.href=result.user.role==='internal'?'/control-center':'/'}catch(loginError){error.textContent=loginError.message;error.hidden=false;submit.disabled=false}});
async function playScenario(){const box=document.querySelector('#scenarioMessages'),actions=document.querySelector('#scenarioActions'),product=selectedProduct();const scripts={inbox:[['Klant','Is de Audi A4 nog beschikbaar?'],[product.name,'Ja. Wilt u ook een proefrit plannen of eerst informatie over inruil ontvangen?'],['Klant','Graag zaterdag een proefrit.'],[product.name,'Ik heb uw voorkeur vastgelegd en controleer de beschikbare momenten.']],followup:[['Lead','Ik heb gisteren een aanvraag voor de Audi A4 gedaan.'],[product.name,'Dank u. Wilt u een proefrit plannen of heeft u eerst een vraag over de auto?'],['Lead','Een proefrit op zaterdag graag.'],[product.name,'Ik controleer de agenda en zet uw voorkeursmoment klaar.']],phone:[['Beller','Goedemiddag, ik wil een werkplaatsafspraak maken.'],[product.name,'Natuurlijk. Om welke auto en welk type onderhoud gaat het?'],['Beller','Een Volkswagen Golf met een onderhoudsmelding.'],[product.name,'Ik bevestig eerst uw contactgegevens en controleer daarna de agenda.']],service:[['Klant','Ik wil graag een serviceafspraak maken.'],[product.name,'Natuurlijk. Ik controleer eerst de auto en uw contactgegevens.'],['Klant','Het gaat om mijn Volkswagen Golf.'],[product.name,'Dinsdag om 10:30 is beschikbaar. Zal ik die reserveren?']]};box.innerHTML='';for(const [speaker,text] of scripts[product.id]||scripts.service){const item=document.createElement('p');item.innerHTML=`<strong>${speaker}</strong><br>${text}`;box.append(item);await new Promise(r=>setTimeout(r,350))}actions.innerHTML=(product.id==='followup'?['Leadbron herkend','Reactie geclassificeerd','Agenda gecontroleerd','Pipeline-concept voorbereid']:product.id==='inbox'?['Kanaal en intentie herkend','Kennis gecontroleerd','Intake aangevuld','CRM-concept voorbereid']:['Vraag herkend','Gegevens bevestigd','Agenda gecontroleerd','CRM-concept voorbereid']).map(x=>`<div class="check-row"><span class="check done">✓</span><strong>${x}</strong></div>`).join('');toast('Scenario voltooid zonder echte externe acties.')}
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.style.background=error?'#9f3826':'';el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}render();renderAccessDecisionControls();renderManagedPanels();
